"""Export of profiles as ``DefaultScalability.ini`` text."""

from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass

from ue_render_profiles_toolset.core.catalog import Catalog
from ue_render_profiles_toolset.core.plan import format_value, require_spec
from ue_render_profiles_toolset.core.profile import Profile
from ue_render_profiles_toolset.errors import CODE_INVALID_PROFILE, ProfileError, clip

LEVEL_INDEX = {"Low": 0, "Medium": 1, "High": 2, "Epic": 3, "Cinematic": 4}
HEADER_LINE_1 = (
    "; Generated by ue-render-profiles-toolset. Profiles: example, validate on your hardware."
)
HEADER_LINE_2 = "; Editor and packaged-game scalability differ; test in a packaged build."


@dataclass(frozen=True)
class IniExport:
    """Ini text and the CVars left out because their catalog entry has no scalability group."""

    text: str
    skipped_cvars: tuple[str, ...]


def render_scalability_ini(levels: Mapping[str, Profile], catalog: Catalog) -> IniExport:
    """Render ``[Group@Level]`` sections for each quality level mapped to a resolved profile."""
    if not levels:
        raise ProfileError(CODE_INVALID_PROFILE, "at least one quality level is required")
    sections: dict[tuple[str, int], dict[str, str]] = {}
    skipped: set[str] = set()
    for level, profile in levels.items():
        index = LEVEL_INDEX.get(level)
        if index is None:
            message = f"unknown quality level: {clip(str(level), 40)}"
            raise ProfileError(CODE_INVALID_PROFILE, message)
        for name, value in profile.cvars.items():
            spec = require_spec(catalog, name)
            if spec.scalability_group is None:
                skipped.add(name)
                continue
            section = sections.setdefault((spec.scalability_group, index), {})
            section[name] = format_value(spec, value)
    lines = [HEADER_LINE_1, HEADER_LINE_2]
    for group, index in sorted(sections):
        lines.append("")
        lines.append(f"[{group}@{index}]")
        entries = sections[(group, index)]
        lines.extend(f"{name}={entries[name]}" for name in sorted(entries))
    return IniExport(text="\n".join(lines) + "\n", skipped_cvars=tuple(sorted(skipped)))
